  '// PHASE 2 STATE',
  '// ============================================================',
  '',
  '// Stage 1: server-resolved access context (populated by WebApp.html template).',
  'var USER_ACCESS = window.__USER_ACCESS__ || { role: \'READ_ONLY\', canViewApp: true, email: \'\' };',
  'var IS_READ_ONLY = (USER_ACCESS.effectiveRole === \'READ_ONLY\' || USER_ACCESS.role === \'READ_ONLY\');',
  '',
  '/**',
  ' * Hides any in-row controls that read-only users should not see.',
  ' * Called after every dynamic render that adds rows to the deployments',
  ' * or go-lives tables.',
  ' */',
  'function applyReadOnlyDomGuards() {',
  '  if (!IS_READ_ONLY) return;',
  '  // Edit buttons inside rendered rows (deployments + go-lives Actions column).',
  '  var editBtns = document.querySelectorAll(\'.action-btn\');',
  '  for (var i = 0; i < editBtns.length; i++) editBtns[i].style.display = \'none\';',
  '  // Meta info cells (the "i" indicator that opens the meta modal).',
  '  var metaCells = document.querySelectorAll(\'.meta-indicator\');',
  '  for (var j = 0; j < metaCells.length; j++) metaCells[j].style.display = \'none\';',
  '  // "View Audit" buttons inside expanded row detail.',
  '  var auditBtns = document.querySelectorAll(\'.detail-actions button[onclick*="openAuditForDeployment"]\');',
  '  for (var k = 0; k < auditBtns.length; k++) auditBtns[k].style.display = \'none\';',
  '  // Defensive: hide any element that calls openEditModal/openGoLivesModal/openMetaModal.',
  '  var modalOpeners = document.querySelectorAll(\'[onclick*="openEditModal"], [onclick*="openGoLivesModal"], [onclick*="openMetaModal"]\');',
  '  for (var m = 0; m < modalOpeners.length; m++) modalOpeners[m].style.display = \'none\';',
  '}',
  '',
  '// Identity, resolved once on page load.',
  'var currentUser = null;       // { email, displayName, role, isAdmin, active, unknown } | null',
  'var activeUsersCache = [];    // Array of AppUsers, populated for VP/PM dropdown',
  '',
  '// Personalization view state. Session-only — no localStorage per Jeff edit 5.',
  '//   { viewMode: \'my\' | \'all\', ddDisplayName: string }',
  '// For DDs: viewMode toggles, ddDisplayName is always self.',
