  '// Global product area filter state (session-only).',
  'var productFilterState = { product: \'all\' };',
  '',
  '// Global filter refresh overlay — tracks active tab + generation to avoid stale hides.',
  'var _filterRefreshTabId_ = null;',
  'var _filterRefreshGen_ = 0;',
  'var _overridesRefreshPending_ = 0;',
  '',
  '// Deployments tab Phase 2 state',
  'var allDeploymentsData = [];          // Phase 2: full portfolio (was deploymentsData/Red+Yellow only)',
  'var deploymentsFilters = {',
  '  search: \'\',',
  '  health: [],                          // [\'Red\', \'Yellow\'] etc.',
  '  owner: \'All\',',
  '  partner: \'All\',',
  '  stage: \'All\',',
