  'var filteredDeployments = [];',
  'var allDeploymentsCountRows = [];       // ProductMode count-grain rows for KPI cards',
  'var filteredDeploymentsCountRows = [];',
  'var deploymentsUseCountGrainKpis = false;',
  'if (!deploymentsFilters.studentFilter) deploymentsFilters.studentFilter = \'All\';',
  'var expandedRowId = null;              // deploymentId of the currently-expanded row, if any',
  'var _deploymentsInflight_ = null;      // { key, gen, waiters } — coalesce concurrent fetches',
  'var _deploymentsFetchGen_ = 0;         // bumped on force refresh / cache invalidation',
  'var _deploymentsImpactBgRequested_ = false;',
  'var _deploymentsDataReady_ = false;    // true after a successful fetch (incl. empty portfolio)',
  'var _deploymentsTableInitialized_ = false;',
