  '// Go-Live Explorer state',
  'var goLivesExplorerData = null;        // last server payload',
  'var filteredGoLives = [];              // rows after client render slice',
  'var goLivesAllRows = [];               // full filtered row set from server',
  'var goLivesRenderedCount = 0;',
  'var goLivesFilters = {',
  '  timePeriod: UI_GLT.defaultTimePeriod || \'next90\',',
  '  customStart: \'\',',
  '  customEnd: \'\',',
  '  fiscalYear: \'\',',
  '  fiscalQuarter: \'All\',',
  '  goLiveType: UI_GLT.defaultGoLiveType || \'upcoming\',',
  '  searchTerm: \'\',',
  '  partner: \'All\',',
  '  health: \'All\',',
